def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return seen[target - n], i
        seen[n] = i
    return -1, -1

i, j = two_sum([2, 7, 11, 15], 9)
print(i, j)

def is_palindrome(s):
    return s == s[::-1]

print(is_palindrome("racecar"))
